/**
 * OtpField. Field's recessed well, cut into one window per digit,
 * in the LCD voice: the code is something the device is reporting, and each
 * character lands in its own lit screen.
 */
.echo-otp {
  /* One size scale (sm/md/lg): each digit's window is the control height. */
  --ctl-h: var(--echo-control-default);
  --ctl-font: var(--echo-text-xl);
  --ctl-radius: var(--echo-radius-lg);
  --otp-slot: 3rem;
  display: flex;
  flex-direction: column;
  gap: var(--echo-space-4);
}
.echo-otp[data-size="sm"] {
  --ctl-h: var(--echo-control-compact);
  --ctl-font: var(--echo-text-lg);
  --ctl-radius: var(--echo-radius-md);
  --otp-slot: 2.25rem;
}
.echo-otp[data-size="lg"] {
  --ctl-h: var(--echo-control-large);
  --ctl-font: var(--echo-text-2xl);
  --ctl-radius: var(--echo-radius-xl);
  --otp-slot: 3.75rem;
}

.echo-otp__label {
  overflow-wrap: anywhere;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-label, 0.2em);
  text-transform: uppercase;
  color: var(--echo-text-dim);
}

.echo-otp__slots {
  display: flex;
  gap: var(--echo-space-4);
  /* The row gives way on a narrow screen rather than setting the width. */
  min-width: 0;
  max-width: 100%;
}

.echo-otp__slot {
  box-sizing: border-box;
  /* One screen per digit: never narrower than a finger, never wider than it
     needs, and the row shares what room there is. */
  flex: 1 1 0;
  min-width: 0;
  max-width: var(--otp-slot);
  height: var(--ctl-h);
  padding: 0;
  border: 0;
  border-radius: var(--ctl-radius);
  text-align: center;
  font-family: var(--echo-font-lcd, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--ctl-font);
  font-variant-numeric: tabular-nums;
  color: var(--echo-accent-ink, var(--echo-accent-glow));
  caret-color: var(--echo-accent-glow);
  text-shadow: 0 0 10px color-mix(in oklab, var(--echo-lcd-glow) 50%, transparent);
  background: linear-gradient(
    160deg,
    color-mix(in oklab, var(--echo-well) 72%, var(--echo-shade-ink, black)),
    color-mix(in oklab, var(--echo-lcd) 88%, var(--echo-shade-ink, black))
  );
  box-shadow:
    inset 0 calc(2px + 3px * var(--well-depth, 0)) calc(5px + 6px * var(--well-depth, 0)) color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1)));
  outline: none;
  transition: box-shadow var(--echo-duration-swap) ease;
}

/* The lit edge marks the slot you're typing into, like the Field's well.
   useWellMotion sinks the window you're on (--well-depth deepens its inner
   shadow) and moves it; nothing here sets a transform. */
.echo-otp__slot:focus-visible {
  /* Drawn only in forced colors, which drops the lit inner edge. */
  outline: var(--echo-border-thick, 2px) solid transparent;
  outline-offset: -2px;
  box-shadow:
    /* The ring first, so the well's top shadow doesn't darken it (BUG-17). */
    inset 0 0 0 var(--echo-border-thick, 2px) var(--echo-accent-ink, var(--echo-accent-glow)),
    inset 0 calc(2px + 3px * var(--well-depth, 0)) calc(5px + 6px * var(--well-depth, 0)) color-mix(in oklab, var(--echo-cast-ink, black) calc(0.7 * var(--echo-shade, 1) * 100%), transparent);
}

.echo-otp[data-disabled] {
  opacity: 0.45;
}
.echo-otp[data-disabled] .echo-otp__slot {
  cursor: not-allowed;
}

.echo-otp[data-invalid] .echo-otp__slot {
  box-shadow:
    inset 0 0 0 var(--echo-border-hairline, 1px) var(--echo-primary-cap-mid),
    inset 0 calc(2px + 3px * var(--well-depth, 0)) calc(5px + 6px * var(--well-depth, 0)) color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent);
}

.echo-otp__description,
.echo-otp__error {
  margin: 0;
  font-size: var(--echo-text-xs);
  line-height: var(--echo-leading-snug, 1.4);
  overflow-wrap: anywhere;
}
.echo-otp__description {
  color: var(--echo-text-dim);
}
.echo-otp__error {
  display: flex;
  gap: var(--echo-space-3);
  align-items: baseline;
  color: var(--echo-text);
}
/* The danger shape, as Banner and Field draw it: words plus a square pip. */
.echo-otp__error::before {
  content: "";
  flex-shrink: 0;
  width: 8px;
  height: 8px;
  border-radius: var(--echo-radius-xs);
  background: var(--echo-primary-cap-mid);
  box-shadow: var(--echo-shadow-edge, inset 0 1px 0 rgb(255 255 255 / calc(0.4 * var(--echo-gloss, 1))));
}

@media (prefers-reduced-motion: reduce) {
  .echo-otp__slot {
    transition: none;
  }
}

/*
 * Forced colors drops the wells' gradients and shadows, which is the whole
 * edge of each window. System colors only, so focus still shows.
 */
@media (forced-colors: active) {
  .echo-otp__slot {
    border: var(--echo-border-hairline, 1px) solid CanvasText;
  }
  .echo-otp__error::before {
    forced-color-adjust: none;
    background: CanvasText;
  }
}

"use client";

/**
 * OtpField. The one-time code a sign-in
 * screen asks for, as a row of lit digit windows — Field's recessed well cut
 * into six screens, in the LCD voice, because a code is something the device
 * reports back at you.
 *
 * On Base UI's OTP Field, so the parts nobody sees are right: a pasted code
 * fills the row, arrow keys and Backspace walk it, `autocomplete="one-time-code"`
 * lets the phone offer the SMS code, and the whole row is one labelled group.
 */
import { forwardRef, useEffect, useRef } from "react";
import type { ReactNode } from "react";
import gsap from "gsap";
import { attachWellMotion, timing, useReducedMotionRef } from "echo-ui-core/tactile";
import type { EchoTextInterop } from "echo-ui-core/types";
import { Field as BaseField } from "@base-ui/react/field";
import { OTPField as BaseOtp } from "@base-ui/react/otp-field";
import { useControlSize, type ControlSize } from "../size";
import "./otp-field.css";

interface OtpFieldOwnProps extends EchoTextInterop {
  /** How many digits. Default 6. */
  length?: number;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Fired when the last slot is filled — where a sign-in screen submits. */
  onComplete?: (value: string) => void;
  /** Hide the characters, for a code that is a secret rather than a one-time one. */
  mask?: boolean;
  /**
   * Height on the control scale: `sm` 32px, `md` 44px (default), `lg` 60px,
   * the same as a Field or HardwareButton of that size. Defaults to the
   * nearest SizeProvider's size.
   */
  size?: ControlSize;
  /** Help text under the row, linked to the group. */
  description?: ReactNode;
  /** What's wrong, in words. While it's set the group is invalid and the message shows. */
  error?: string;
}

/**
 * A field has to have a name. A visible `label` is
 * the one to reach for; `aria-label` or `aria-labelledby` are for a field whose
 * label is elsewhere on screen. Leaving all three out is a type error.
 */
type FieldName =
  | { label: string; "aria-label"?: string; "aria-labelledby"?: string }
  | { "aria-label": string; label?: string; "aria-labelledby"?: string }
  | { "aria-labelledby": string; label?: string; "aria-label"?: string };

export type OtpFieldProps = OtpFieldOwnProps & FieldName;

/**
 * `forwardRef`, not a `ref` prop — see the note on `Field`.
 *
 * The ref lands on the FIRST slot. A one-time code is one value spread over
 * several inputs, and the first is the one `shouldFocusError` should land on
 * — focusing the last slot would put the caret past the digits the user
 * still has to fix.
 */
export const OtpField = forwardRef<HTMLInputElement, OtpFieldProps>(function OtpField(
  {
    label,
    length = 6,
    value,
    defaultValue,
    onValueChange,
    onComplete,
    disabled,
    size: ownSize,
    required,
    name,
    mask,
    description,
    error,
    id,
    autoFocus,
    onBlur,
    onFocus,
    onKeyDown,
    autoComplete,
    "aria-label": ariaLabel,
    "aria-labelledby": ariaLabelledby,
  },
  ref,
) {
  const reduced = useReducedMotionRef();
  const size = useControlSize(ownSize);
  const slots = useRef<HTMLDivElement | null>(null);
  const cells = () => [...(slots.current?.querySelectorAll<HTMLElement>(".echo-otp__slot") ?? [])];

  /* Each window is a well (useWellMotion): the one you're on sinks, so the
     press travels along the row with you, and each digit lands as a strike. */
  useEffect(() => {
    const detach = cells().map(attachWellMotion);
    return () => detach.forEach((d) => d());
  }, [length]);

  /* The whole code in: a ripple runs along the row. */
  const completed = () => {
    if (reduced.current) return;
    gsap.fromTo(
      cells(),
      // yPercent, not y: y is the well's own sink, and the two add up.
      { yPercent: 0 },
      { keyframes: [{ yPercent: -8, duration: 0.12, ease: "power2.out" }, { yPercent: 0, ...timing("rebound") }], stagger: 0.05 },
    );
  };
  return (
    <BaseField.Root className="echo-otp" data-size={size} disabled={disabled} invalid={error ? true : undefined}>
      {label && <BaseField.Label className="echo-otp__label">{label}</BaseField.Label>}
      <BaseOtp.Root
        ref={slots}
        className="echo-otp__slots"
        length={length}
        name={name}
        value={value}
        defaultValue={defaultValue}
        required={required}
        disabled={disabled}
        mask={mask}
        onValueChange={onValueChange}
        onValueComplete={(next) => {
          completed();
          onComplete?.(next);
        }}
        aria-label={label ? undefined : ariaLabel}
        aria-labelledby={label ? undefined : ariaLabelledby}
      >
        {Array.from({ length }, (_, i) => (
          <BaseOtp.Input
            key={i}
            className="echo-otp__slot"
            ref={i === 0 ? ref : undefined}
            {...(i === 0 && id ? { id } : {})}
            {...(i === 0 && autoFocus ? { autoFocus } : {})}
            /*
             * Spread only when set. Base UI gives every window its own
             * `autocomplete="one-time-code"` and its own key handling, and
             * passing an explicit `undefined` overrides them — which is how
             * the phone stopped offering the code it had just received.
             */
            {...(i === 0 && autoComplete ? { autoComplete } : {})}
            {...(onBlur ? { onBlur } : {})}
            {...(onFocus ? { onFocus } : {})}
            {...(onKeyDown ? { onKeyDown } : {})}
          />
        ))}
      </BaseOtp.Root>
      {description != null && <BaseField.Description className="echo-otp__description">{description}</BaseField.Description>}
      {error && (
        <BaseField.Error className="echo-otp__error" match>
          {error}
        </BaseField.Error>
      )}
    </BaseField.Root>
  );
});
